-- Charades curated V2: 1,152 active prompts, 1,682 preserved archives.
-- Generated by scripts/generate-charades-v6-content.mjs.

begin;

on conflict(game_id,category_id) do update set label=excluded.label,target_count=excluded.target_count,sort_order=excluded.sort_order,enabled=true,updated_at=now();

update public.content_categories set enabled=false,updated_at=now()
where game_id='charades' and category_id not in ('animals','food-drinks','hobbies','scenes-skits','sports','tech-gadgets','weather-nature','famous-people','movies','songs','tv-shows');

create temporary table decked_charades_v2_active(item_id uuid primary key,category_id text not null,sort_order integer not null,metadata jsonb not null) on commit drop;


create temporary table decked_charades_v2_archive(item_id uuid primary key) on commit drop;


update public.content_items i set lifecycle_status='active',updated_at=now()
from decked_charades_v2_active selected where i.id=selected.item_id and i.game_id='charades';

update public.content_items i set lifecycle_status='archived',updated_at=now()
from decked_charades_v2_archive retired where i.id=retired.item_id and i.game_id='charades';

update public.content_item_categories set enabled=false where game_id='charades';

select item_id,'charades',category_id,sort_order,true from decked_charades_v2_active
on conflict(item_id,game_id,category_id) do update set sort_order=excluded.sort_order,enabled=true;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata
from decked_charades_v2_active selected join public.content_items item on item.id=selected.item_id
where version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='charades' and status='published';

values('5c1b66d4-8e52-5e06-b6f0-0f2edc75a4ec'::uuid,'charades','published',1152,1152,'8f492f2cc2c2c0168eb36723e1049e970fd427c9413fc726c44586d94c7e6cba','Charades curated V2 baseline; archived identities preserved.',now())
on conflict(id) do update set status='published',item_count=1152,membership_count=1152,checksum=excluded.checksum,notes=excluded.notes,published_at=now();

delete from public.content_release_items where release_id='5c1b66d4-8e52-5e06-b6f0-0f2edc75a4ec'::uuid;

select '5c1b66d4-8e52-5e06-b6f0-0f2edc75a4ec'::uuid,item.id,item.published_version,array[selected.category_id]
from decked_charades_v2_active selected join public.content_items item on item.id=selected.item_id
where item.game_id='charades' and item.published_version is not null;

commit;
